typedef float rational_t;
typedef unsigned short uint16;

struct string_buf
{
  int refs;
  int capacity;
  int char_length;
};

class stringx
{
  char *chars;
  string_buf *my_buf;

public:
  stringx();
  stringx(const stringx &cp);
  stringx(const char *str, int len = -1);
  ~stringx();
  void append(const char *str, int len = -1);
  void append(const stringx &cp);
  void make_room(int n);
  stringx &operator+=(const char *str);

  friend stringx operator+(const stringx &lhs, const stringx &rhs);
  friend stringx operator+(const stringx &lhs, const char *rhs);
};

extern "C" int strlen(const char *);

inline stringx operator+(const stringx &lhs, const stringx &rhs)
{
  stringx foo;
  foo.make_room(lhs.my_buf->char_length + rhs.my_buf->char_length);
  foo.append(lhs);
  foo.append(rhs);
  return foo;
}

inline stringx operator+(const stringx &lhs, const char *rhs)
{
  stringx foo;
  int len = strlen(rhs);
  foo.make_room(len + lhs.my_buf->char_length);
  foo.append(lhs);
  foo.append(rhs, len);
  return foo;
}

class entity_anim_tree;
class vector3d;

class entity
{
  char padding[0x84];
  stringx parsedName;

public:
  stringx get_parsed_name() { return parsedName; }
  void load_anim(const stringx &filename) const;
  entity_anim_tree *play_anim(int slot, const stringx &filename,
                              rational_t start_time, uint16 anim_flags = 0,
                              short loop = -1);
};

class entity_track_tree
{
public:
  static const char *extension();
};

bool file_finder_exists(const stringx &filename, const stringx &extension,
                        stringx *found_name = 0);

class beach_object
{
protected:
  char padding0[0x28];
  entity *my_entity;
  char padding1[0x0c];
};

class water_object : public beach_object
{
public:
  water_object(entity *ent, const stringx &path);
  virtual ~water_object();
  virtual bool parse_params(char **argp, int argc);
  virtual void get_settings(const water_object &obj);
  virtual void spawn();
  virtual void despawn();
  virtual bool update(float dt);
  virtual void collide(entity *ent, const vector3d &dir);
  virtual void jumped_over(entity *ent);
  virtual void sprayed(entity *ent);

protected:
  char padding2[0x294];
};

class static_object : public water_object
{
public:
  static_object(entity *ent, const stringx &path);
  virtual ~static_object();
  bool update(float dt);
  virtual bool parse_params(char **argp, int argc);

private:
  bool dont_move;
};

static_object::static_object(entity *ent, const stringx &path)
  : water_object(ent, path)
{
  dont_move = false;

  stringx anim = path + "\\ANIMATIONS\\" + ent->get_parsed_name();

  if (file_finder_exists(anim, entity_track_tree::extension()))
  {
    anim += entity_track_tree::extension();
    my_entity->load_anim(anim);
    my_entity->play_anim(0, ent->get_parsed_name(), 0.3f, 4 | 512 | 2048);
  }
}
